long long isqrt_exact(long long x) {
    if (x <= 0) return 0;
    long long r = (long long)sqrtl((long double)x);
    while (r + 1 <= x / (r + 1)) ++r;
    while (r > 0 && r > x / r) --r;
    return r;
}

