#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

long long modpow(long long base, long long exp, long long mod) {
    long long res = 1 % mod;
    base %= mod;
    while (exp > 0) {
        if (exp & 1LL) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1LL;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    if (!(cin >> T)) return 0;
    while (T--) {
        long long a, b, c;
        cin >> a >> b >> c;
        if (c == 0) {
            cout << (a % MOD) << '\n';
        } else if (b == 0) {
            cout << 1 << '\n';
        } else if (a % MOD == 0) {
            cout << 0 << '\n';
        } else {
            long long e = modpow(b, c, MOD - 1);
            cout << modpow(a, e, MOD) << '\n';
        }
    }
    return 0;
}
